                $display("Error: Expected q = 0000 after count %d, got q = %b", j, q);
                errors = errors + 1;
            end
        end

        // Check results
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
